package pe.vichaval.gestionriego.parcela.controller;import jakarta.validation.Valid;import org.springframework.stereotype.*;import org.springframework.ui.*;import org.springframework.validation.*;import org.springframework.web.bind.annotation.*;import pe.vichaval.gestionriego.agricultor.repository.*;import pe.vichaval.gestionriego.parcela.dto.*;import pe.vichaval.gestionriego.parcela.entity.*;import pe.vichaval.gestionriego.parcela.repository.*;@Controller@RequestMapping("/parcelas")public class ParcelaWebController{private final ParcelaRepository r;private final AgricultorRepository a;public ParcelaWebController(ParcelaRepository r,AgricultorRepository a){this.r=r;this.a=a;}@GetMapping String list(Model m){m.addAttribute("parcelas",r.findAll());return "parcela/list";}@GetMapping("/nueva")String form(Model m){m.addAttribute("form",new ParcelaForm());m.addAttribute("agricultores",a.findAll());return "parcela/form";}@PostMapping String save(@Valid@ModelAttribute("form")ParcelaForm f,BindingResult b,Model m){if(r.existsByCodigoIgnoreCase(f.getCodigo()))b.rejectValue("codigo","dup","Código duplicado");if(b.hasErrors()){m.addAttribute("agricultores",a.findAll());return "parcela/form";}r.save(new Parcela(f,a.findById(f.getAgricultorId()).orElseThrow()));return "redirect:/parcelas";}}